STYLES_CSS += r'''.company-fact-sections{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px;margin:16px 0 25px}.fact-section{border:1px solid var(--line);border-radius:10px;padding:13px;background:#fff}.fact-section[open]{grid-column:1/-1}.fact-section summary{cursor:pointer;font-weight:800}.fact-status{display:block;color:var(--green);font-size:10px;letter-spacing:.05em;margin:5px 0}.fact-reason{color:var(--muted);font-size:12px}.fact-values{display:grid;grid-template-columns:repeat(auto-fit,minmax(170px,1fr));gap:7px;margin-top:10px}.fact-value{background:#f7f9f8;border-radius:7px;padding:8px;overflow-wrap:anywhere}.fact-value small{display:block;color:var(--muted)}.peer-list{margin:8px 0;padding-left:20px}@media(max-width:700px){.company-fact-sections{grid-template-columns:1fr}.fact-section[open]{grid-column:auto}}'''

